<?php
require_once __DIR__ . '/env.php';require_once __DIR__ . '/db.php';
function payment_order(string $no): array{$q=db()->prepare('SELECT order_no,status,payment_method,subtotal,discount,shipping,total,customer_name,phone,email,address,city FROM orders WHERE order_no=?');$q->execute([$no]);$o=$q->fetch();if(!$o)api_json(404,['ok'=>false,'error'=>'Order not found']);if($o['status']==='paid')api_json(409,['ok'=>false,'error'=>'Order is already paid']);return $o;}
function mark_order_paid(string $no,string $ref): void{$q=db()->prepare("UPDATE orders SET status='paid',gateway_ref=? WHERE order_no=? AND status='pending'");$q->execute([$ref,$no]);$q=db()->prepare("UPDATE customer_orders SET status='paid' WHERE order_no=? AND status='pending'");$q->execute([$no]);}
function api_method(string $method): void{if(($_SERVER['REQUEST_METHOD']??'')!==$method)api_json(405,['ok'=>false,'error'=>'Method not allowed']);}
function api_input(): array{$d=json_decode(file_get_contents('php://input'),true);return is_array($d)?$d:[];}
function gateway_post(string $url,array $headers,string $body): array{if(!function_exists('curl_init'))throw new RuntimeException('PHP cURL extension is required');$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_HTTPHEADER=>$headers,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>12,CURLOPT_TIMEOUT=>30]);$raw=curl_exec($ch);$error=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($raw===false)throw new RuntimeException('Gateway connection failed: '.$error);$data=json_decode($raw,true);if(!is_array($data))throw new RuntimeException('Gateway returned invalid response (HTTP '.$code.')');return['http'=>$code,'data'=>$data];}
function order_prefix(string $no,string $prefix): string{return preg_match('/^[A-Z]{2}-/',$no)?$no:$prefix.'-'.preg_replace('/^.*?-/','',$no);}
